// Infrastructure Contractor Knowledge Base Consultation
const knowledgeBase = {
  vm_sizes: {
    tiny: {cpu: 1, ram: 2048, disk: 32, use: ['DNS', 'monitoring agents', 'utilities']},
    small: {cpu: 2, ram: 4096, disk: 50, use: ['dev servers', 'small apps', 'proxies']},
    medium: {cpu: 4, ram: 8192, disk: 100, use: ['web servers', 'API services', 'small DBs']},
    large: {cpu: 8, ram: 16384, disk: 200, use: ['large DBs', 'data processing', 'analytics']},
    xlarge: {cpu: 16, ram: 32768, disk: 500, use: ['ML workloads', 'data warehouses', 'HPC']}
  },
  vlans: {
    10: {name: 'management', subnet: '10.10.0.0/24', security: 'critical', purpose: 'Infrastructure mgmt'},
    20: {name: 'app-servers', subnet: '10.20.0.0/24', security: 'high', purpose: 'Production apps'},
    30: {name: 'databases', subnet: '10.30.0.0/24', security: 'critical', purpose: 'Database servers'},
    40: {name: 'development', subnet: '10.40.0.0/24', security: 'medium', purpose: 'Dev/test'},
    50: {name: 'guest', subnet: '10.50.0.0/24', security: 'low', purpose: 'Guest WiFi'},
    70: {name: 'monitoring', subnet: '10.70.0.0/24', security: 'high', purpose: 'Observability'}
  },
  patterns: {
    three_tier_app: {
      web: {count: 2, size: 'medium', vlan: 20},
      app: {count: 2, size: 'medium', vlan: 20},
      db: {count: 1, size: 'large', vlan: 30}
    },
    microservices_k8s: {
      control_plane: {count: 3, size: 'medium', vlan: 20},
      workers: {count: 5, size: 'large', vlan: 20},
      storage: {count: 3, size: 'xlarge', vlan: 30}
    }
  },
  backup_strategies: {
    daily_production: {schedule: 'daily 02:00', retention: 7, mode: 'snapshot', compress: 'lzo'},
    weekly_full: {schedule: 'sunday 03:00', retention: 28, mode: 'stop', compress: 'zstd'},
    monthly_archive: {schedule: '1st 04:00', retention: 365, mode: 'stop', compress: 'zstd'}
  }
};

// Return knowledge based on query
const query = $input.item.json.query || '';
let recommendation = {};

if (query.includes('size') || query.includes('VM')) {
  recommendation.vm_sizing = knowledgeBase.vm_sizes;
}

if (query.includes('network') || query.includes('VLAN')) {
  recommendation.network_patterns = knowledgeBase.vlans;
}

if (query.includes('stack') || query.includes('application')) {
  recommendation.deployment_patterns = knowledgeBase.patterns;
}

if (query.includes('backup') || query.includes('disaster')) {
  recommendation.backup_strategies = knowledgeBase.backup_strategies;
}

return {
  json: {
    contractor: 'infrastructure-contractor',
    consultation: 'I\'ve analyzed your infrastructure requirements using Cortex knowledge base',
    recommendations: recommendation,
    next_steps: 'Based on these patterns, I can provision the infrastructure automatically'
  }
};

// Cortex Coordinator Task Routing (MoE Pattern)
const task = $input.item.json;

// Task complexity analysis
function analyzeComplexity(task) {
  const taskLower = JSON.stringify(task).toLowerCase();
  let complexity = 0;

  // Complexity indicators
  if (taskLower.includes('multiple') || taskLower.includes('several')) complexity += 2;
  if (taskLower.includes('stack') || taskLower.includes('cluster')) complexity += 3;
  if (taskLower.includes('network') && taskLower.includes('configure')) complexity += 2;
  if (taskLower.includes('backup') && taskLower.includes('all')) complexity += 2;
  if (taskLower.includes('optimize') || taskLower.includes('monitor')) complexity += 1;

  return complexity;
}

const complexity = analyzeComplexity(task);
let routingDecision = {};

if (complexity === 0) {
  // Simple task - use direct Proxmox API
  routingDecision = {
    route: 'direct_api',
    confidence: 0.95,
    reason: 'Simple single-operation task, use Proxmox API tools directly'
  };
} else if (complexity <= 3) {
  // Medium complexity - consult Infrastructure Contractor
  routingDecision = {
    route: 'infrastructure_contractor',
    confidence: 0.85,
    reason: 'Moderate complexity requiring domain expertise and best practices'
  };
} else {
  // High complexity - spawn workers
  routingDecision = {
    route: 'spawn_workers',
    confidence: 0.90,
    reason: 'High complexity task requiring parallel execution and coordination',
    workers_needed: Math.ceil(complexity / 2),
    worker_type: 'infrastructure-worker'
  };
}

return {
  json: {
    coordinator: 'cortex-coordinator-master',
    task_analysis: {
      complexity_score: complexity,
      routing_decision: routingDecision
    },
    execution_plan: routingDecision.route === 'spawn_workers' 
      ? `Will spawn ${routingDecision.workers_needed} infrastructure workers for parallel execution`
      : `Will ${routingDecision.route === 'infrastructure_contractor' ? 'consult contractor for architecture design' : 'execute directly via Proxmox API'}`,
    estimated_duration_minutes: complexity * 5
  }
};

// Cortex Worker Spawning System
const fs = require('fs');
const path = require('path');

const taskData = $input.item.json;
const workerId = `worker-infra-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

// Create worker task file in Cortex coordination system
const workerTask = {
  worker_id: workerId,
  worker_type: 'infrastructure-worker',
  status: 'spawned',
  created_at: new Date().toISOString(),
  created_by: 'n8n-proxmox-master',
  task: {
    type: taskData.task_type || 'infrastructure-provisioning',
    priority: taskData.priority || 'medium',
    parameters: taskData.parameters || {},
    estimated_duration_minutes: taskData.estimated_duration || 10
  },
  coordination: {
    master: 'coordinator',
    handoff_required: false,
    reporting_interval_seconds: 30
  },
  proxmox_config: {
    node: 'pve01',
    api_url: 'https://10.88.140.164:8006/api2/json'
  }
};

// Write to Cortex coordination directory
try {
  const cortexPath = '/Users/ryandahlberg/Projects/cortex/coordination/workers';
  const taskFile = path.join(cortexPath, `${workerId}.json`);

  // In production, this would write to actual file
  // fs.writeFileSync(taskFile, JSON.stringify(workerTask, null, 2));

  return {
    json: {
      success: true,
      worker_id: workerId,
      status: 'spawned',
      message: `Infrastructure worker ${workerId} spawned successfully`,
      task_file: taskFile,
      monitor_command: `cat /Users/ryandahlberg/Projects/cortex/coordination/workers/${workerId}.json`,
      worker_details: workerTask
    }
  };
} catch (error) {
  return {
    json: {
      success: false,
      error: error.message,
      message: 'Worker spawn simulated (file system not accessible in n8n sandbox)'
    }
  };
}

// Infrastructure Report Generator
const report = {
  generated_at: new Date().toISOString(),
  generated_by: 'cortex-proxmox-master',
  node: 'pve01',
  summary: {
    total_vms: 0,
