    network_segmentation: 0
  },
  next_actions: [
    'Review VMs with high CPU usage',
    'Check backup coverage for all production VMs',
    'Validate network segmentation follows VLAN patterns',
    'Verify disaster recovery procedures'
  ]
};

// In production, this would aggregate data from all Proxmox API calls
report.summary.note = 'This is a template. In production, actual VM/LXC data would be aggregated here.';

return {
  json: {
    report: report,
    format: 'json',
    export_formats: ['json', 'markdown', 'html', 'pdf'],
