// Get input parameters
const toolName = $input.item.json.tool_name;
const toolDesc = $input.item.json.tool_description;
const toolImpl = $input.item.json.tool_implementation;

// Get current workflow
const currentWorkflow = $input.item.json.current_workflow;

// Find max node ID
let maxId = 0;
for (const node of currentWorkflow.nodes) {
  const id = parseInt(node.id.split('-').pop());
  if (!isNaN(id) && id > maxId) maxId = id;
}

// Create new tool node
const newToolNode = {
  id: `tool-${toolName}-${maxId + 1}`,
  name: `Tool: ${toolName}`,
  type: "@n8n/n8n-nodes-langchain.toolWorkflow",
  position: [880, (maxId + 1) * 100],
  parameters: {
    name: toolName,
    description: toolDesc,
    workflowId: "={{ $workflow.id }}",
    specifyInputSchema: True,
    jsonSchemaExample: "{}"
  }
};

// Create implementation node (HTTP request)
const implNode = {
  id: `http-${toolName}-${maxId + 2}`,
  name: `Implementation: ${toolName}`,
  type: "n8n-nodes-base.httpRequest",
  position: [1080, (maxId + 1) * 100],
  parameters: toolImpl
};

// Add nodes to workflow
currentWorkflow.nodes.push(newToolNode);
currentWorkflow.nodes.push(implNode);

// Add connection from tool to implementation
if (!currentWorkflow.connections[newToolNode.name]) {
  currentWorkflow.connections[newToolNode.name] = {main: [[{node: implNode.name, type: "main", index: 0}]]};
}

// Add connection from tool to agent
const agentNode = currentWorkflow.nodes.find(n => n.type.includes('agent'));
if (agentNode) {
  currentWorkflow.connections[newToolNode.name] = currentWorkflow.connections[newToolNode.name] || {};
  currentWorkflow.connections[newToolNode.name].ai_tool = [[{node: agentNode.name, type: "ai_tool", index: 0}]];
}

return {json: {updated_workflow: currentWorkflow}};

// Get input
const newInstructions = $input.item.json.new_instructions;
const currentWorkflow = $input.item.json.current_workflow;

// Find agent node
const agentNode = currentWorkflow.nodes.find(n => n.type.includes('agent'));
if (agentNode) {
  agentNode.parameters.text = newInstructions;
}

return {json: {updated_workflow: currentWorkflow}};

